#ifndef TF_FORM_LOGIC_H
#define TF_FORM_LOGIC_H
#include "control_logic.h"
#include "sms_submit.h"
#include <stdint.h>
static int tf_ascii_append(char*s,size_t cap,unsigned ch,size_t maximum){size_t n=strlen(s);if(ch<32||ch>126||n>=maximum||n+1>=cap)return 0;s[n]=(char)ch;s[n+1]=0;return 1;}
static void tf_utf8_backspace(char*s){size_t n=strlen(s);if(!n)return;n--;while(n&&((unsigned char)s[n]&0xc0)==0x80)n--;s[n]=0;}
/* Convert well-formed UTF-8 to UTF-16BE hex required by the existing SMS API. */
static int tf_sms_utf16_hex(char*out,size_t cap,const char*text){size_t length=strlen(text),i=0,n=0;int nonblank=0;if(!length||length>512)return 0;while(i<length){uint32_t cp;unsigned char first=(unsigned char)text[i++];int follow=0;uint32_t minimum=0;if(first<0x80)cp=first;else if(first>=0xc2&&first<=0xdf){cp=first&0x1f;follow=1;minimum=0x80;}else if(first>=0xe0&&first<=0xef){cp=first&0xf;follow=2;minimum=0x800;}else if(first>=0xf0&&first<=0xf4){cp=first&7;follow=3;minimum=0x10000;}else return 0;if(i+(size_t)follow>length)return 0;for(int k=0;k<follow;k++){unsigned char b=(unsigned char)text[i++];if((b&0xc0)!=0x80)return 0;cp=(cp<<6)|(b&0x3f);}if(cp<minimum||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff)||(cp<32&&cp!=10&&cp!=13)||(cp>=0x7f&&cp<=0x9f))return 0;if(cp>32&&cp!=0x3000)nonblank=1;if(cp<=0xffff){if(n+4>=cap)return 0;snprintf(out+n,5,"%04X",(unsigned)cp);n+=4;}else{if(n+8>=cap)return 0;cp-=0x10000;snprintf(out+n,9,"%04X%04X",(unsigned)(0xd800+(cp>>10)),(unsigned)(0xdc00+(cp&1023)));n+=8;}}out[n]=0;return nonblank;}
static int tf_sms_payload(char*out,size_t cap,const char*number,const char*message,const char*timestamp){size_t n=strlen(number);if(n<3||n>32)return 0;for(size_t i=0;i<n;i++)if(!(i==0&&number[i]=='+')&&!isdigit((unsigned char)number[i]))return 0;char hex[2049];if(!tf_sms_utf16_hex(hex,sizeof hex,message))return 0;char timeq[128];if(!tf_quote(timeq,sizeof timeq,timestamp))return 0;int k=snprintf(out,cap,"{\"action\":\"sms.send_raw\",\"params\":{\"sender\":\"host\",\"number\":\"%s\",\"message_hex\":\"%s\",\"sms_time\":%s}}",number,hex,timeq);return k>0&&(size_t)k<cap;}
/* Numeric manual entry is independent of the currently serving cell. */
static int tf_cell_number(const char*s,long long max,long long*out){if(!s||!*s||strlen(s)>7)return 0;for(const char*p=s;*p;p++)if(*p<'0'||*p>'9')return 0;char*end;long long n=strtoll(s,&end,10);if(*end||n<0||n>max)return 0;*out=n;return 1;}
static int tf_cell_manual_payload(char*out,size_t cap,const tf_json*d,int nr,const char*pci_text,const char*channel_text,const char*band_text){
 long long pci,channel,band=0;if(nr!=0&&nr!=1)return 0;if(tf_key(d,0,"net")<0||!tf_cell_number(pci_text,nr?1007:503,&pci)||!tf_cell_number(channel_text,nr?3279165:262143,&channel)||channel==0)return 0;
 if(nr){unsigned char sa[TF_BANDS],nsa[TF_BANDS],selected[TF_BANDS];if(!tf_cell_number(band_text,512,&band)||band<1)return 0;int has_sa=tf_band_snapshot(d,1,sa,selected),has_nsa=tf_band_snapshot(d,2,nsa,selected);if((!has_sa||!sa[band])&&(!has_nsa||!nsa[band]))return 0;}
 int n=nr?snprintf(out,cap,"{\"action\":\"cell.lock_nr\",\"params\":{\"pci\":%lld,\"arfcn\":%lld,\"band\":%lld}}",pci,channel,band):snprintf(out,cap,"{\"action\":\"cell.lock_lte\",\"params\":{\"pci\":%lld,\"earfcn\":%lld}}",pci,channel);return n>0&&(size_t)n<cap;
}
static const char*tf_wifi_enc[]={"none","psk2+ccmp","sae-mixed","sae","psk-mixed+tkip+ccmp","psk2","psk-mixed"};
static int tf_wifi_enc_index(const char*s){for(int i=0;i<7;i++)if(!strcmp(s,tf_wifi_enc[i]))return i;return-1;}
static int tf_wifi_payload(char*out,size_t cap,const char*band,const char*ssid,const char*password,const char*encryption,const char*oldssid,const char*oldenc){if(strcmp(band,"2g")&&strcmp(band,"5g")&&strcmp(band,"guest_2g")&&strcmp(band,"guest_5g"))return 0;size_t n=strlen(ssid),keyn=strlen(password);if(n<1||n>32||tf_wifi_enc_index(encryption)<0||(keyn&&(keyn<8||keyn>63))||(!strcmp(oldenc,"none")&&strcmp(encryption,"none")&&!keyn))return 0;char sq[256],kq[256],eq[128];if(!tf_quote(sq,sizeof sq,ssid)||!tf_quote(kq,sizeof kq,password)||!tf_quote(eq,sizeof eq,encryption))return 0;size_t written=(size_t)snprintf(out,cap,"{\"action\":\"wifi.configure\",\"params\":{\"section\":\"%s%s\"",!strncmp(band,"guest_",6)?"":"main_",band);int changed=0;if(strcmp(ssid,oldssid)){written+=(size_t)snprintf(out+written,cap-written,",\"ssid\":%s",sq);changed=1;}if(strcmp(encryption,oldenc)){written+=(size_t)snprintf(out+written,cap-written,",\"encryption\":%s",eq);changed=1;}if(keyn){written+=(size_t)snprintf(out+written,cap-written,",\"key\":%s",kq);changed=1;}if(!changed||written+3>=cap)return 0;snprintf(out+written,cap-written,"}}");return 1;}
#endif
